<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';
if($_SERVER['REQUEST_METHOD']!=='POST')gpme_json(['ok'=>false,'error'=>'Méthode non autorisée'],405);
try{$in=json_decode(file_get_contents('php://input'),true,512,JSON_THROW_ON_ERROR);$rid=trim((string)($in['resource_id']??''));$title=trim((string)($in['resource_title']??''));$section=trim((string)($in['section']??''));$category=trim((string)($in['category']??''));$comment=trim((string)($in['comment']??''));$url=trim((string)($in['page_url']??''));if($rid===''||$title===''||$category===''||$comment==='')gpme_json(['ok'=>false,'error'=>'Champs incomplets'],422);if(mb_strlen($comment)>3000)gpme_json(['ok'=>false,'error'=>'Commentaire trop long'],422);$db=gpme_db();$st=$db->prepare('INSERT INTO feedback(resource_id,resource_title,section,category,comment,page_url) VALUES(?,?,?,?,?,?)');$st->execute([$rid,$title,$section,$category,$comment,$url]);gpme_json(['ok'=>true,'id'=>(int)$db->lastInsertId(),'status'=>'pending']);}catch(Throwable $e){gpme_json(['ok'=>false,'error'=>$e->getMessage()],500);}?>